## Summary

Implement the engine that evaluates task selection rules against candidate tasks.

## Interface

```go
// pkg/rules/engine.go

type Engine struct {
    config  *config.RulesSettings
    runtime []CustomRule  // Runtime-added rules (in-memory)
    mu      sync.RWMutex
}

func NewEngine(config *config.RulesSettings) *Engine

// Evaluate returns whether a task should be selected
// and any modifications (e.g., priority boost)
type EvalResult struct {
    Allow       bool
    Skip        bool
    SkipReason  string
    BoostAmount int
    LimitKey    string  // For concurrency limiting
    LimitMax    int
}

func (e *Engine) Evaluate(task *beads.Task, inFlight map[string]bool) EvalResult
```

## Evaluation Order

```go
func (e *Engine) Evaluate(task *beads.Task, inFlight map[string]bool) EvalResult {
    result := EvalResult{Allow: true}

    // 1. Priority range check
    if task.Priority < e.config.PriorityMin || task.Priority > e.config.PriorityMax {
        return EvalResult{Skip: true, SkipReason: "outside priority range"}
    }

    // 2. Type whitelist/blacklist
    if len(e.config.Types) > 0 && !contains(e.config.Types, task.Type) {
        return EvalResult{Skip: true, SkipReason: "type not in whitelist"}
    }
    if contains(e.config.ExcludeTypes, task.Type) {
        return EvalResult{Skip: true, SkipReason: "type in blacklist"}
    }

    // 3. Label whitelist/blacklist
    // ... similar logic

    // 4. Assignee check
    if e.config.Assignee == "" && task.Assignee != "" {
        return EvalResult{Skip: true, SkipReason: "task is assigned"}
    }

    // 5. Concurrency limits
    typeCount := countInFlightByType(inFlight, task.Type)
    if limit, ok := e.config.MaxConcurrentPerType[task.Type]; ok {
        if typeCount >= limit {
            return EvalResult{Skip: true, SkipReason: fmt.Sprintf("type %s at limit", task.Type)}
        }
    }

    // 6. Custom rules (config + runtime)
    for _, rule := range e.allRules() {
        if !rule.Enabled {
            continue
        }
        if matches := e.evalCondition(rule.Condition, task); matches {
            switch rule.Action {
            case "skip":
                return EvalResult{Skip: true, SkipReason: rule.Reason}
            case "boost":
                result.BoostAmount += rule.BoostAmount
            case "limit":
                result.LimitKey = rule.Name
                result.LimitMax = rule.Limit
            case "allow":
                // Explicit allow - skip remaining rules
                return EvalResult{Allow: true, BoostAmount: result.BoostAmount}
            }
        }
    }

    return result
}
```

