## Summary

On daemon startup, detect and recover orphaned overlays from previous runs.

## Background

When daemon crashes or restarts while agents are running:
- Overlays remain mounted (or partially mounted)
- `active_overlays` table has records with status="active"
- These are now "orphaned" - no process owns them

Recovery has two paths:
1. **Resumable**: Has session_id → can resume agent
2. **Non-resumable**: No session_id → cleanup only

## Implementation

### 1. Recovery function (`pkg/daemon/recovery.go`)

```go
type OverlayRecoveryResult struct {
    Resumed   int  // Overlays with agents resumed
    Cleaned   int  // Overlays cleaned up (no session_id)
    Failed    int  // Recovery failures
    Errors    []error
}

func (d *Daemon) RecoverOrphanedOverlays(ctx context.Context) (*OverlayRecoveryResult, error) {
    result := &OverlayRecoveryResult{}

    overlays, err := d.persistence.GetActiveOverlays()
    if err \!= nil {
        return nil, fmt.Errorf("failed to get active overlays: %w", err)
    }

    for _, o := range overlays {
        if o.SessionID \!= "" {
            // Can resume - will be handled by agent recovery
            result.Resumed++
            continue
        }

        // No session_id - cleanup only
        if err := d.cleanupOrphanedOverlay(o); err \!= nil {
            result.Failed++
            result.Errors = append(result.Errors, err)
            continue
        }
        result.Cleaned++
    }

    return result, nil
}

func (d *Daemon) cleanupOrphanedOverlay(o *persistence.ActiveOverlay) error {
    // Try to unmount if still mounted
    if sandbox.IsMounted(o.MergedDir) {
        if err := sandbox.Unmount(o.MergedDir); err \!= nil {
            // Log but continue - may already be unmounted
            log.Printf("warning: failed to unmount %s: %v", o.MergedDir, err)
        }
    }

    // Remove overlay directories
    // (upper_dir and work_dir - lower_dir is the repo, dont touch)
    os.RemoveAll(o.UpperDir)
    os.RemoveAll(o.WorkDir)

    // Mark as cleaned in DB
    return d.persistence.DeleteOverlay(o.AgentID)
}
```

### 2. Integrate into daemon startup (`pkg/daemon/daemon.go`)

```go
func (d *Daemon) Init(ctx context.Context) error {
    // ... existing init ...

    // Recover orphaned overlays before accepting new work
    if d.persistence \!= nil {
        result, err := d.RecoverOrphanedOverlays(ctx)
        if err \!= nil {
            return fmt.Errorf("overlay recovery failed: %w", err)
        }
        if result.Resumed > 0 || result.Cleaned > 0 {
            log.Printf("Overlay recovery: %d resumable, %d cleaned, %d failed",
                result.Resumed, result.Cleaned, result.Failed)
        }
    }

    return nil
}
```

