### 2. Rules Engine Persist Method

```go
// pkg/rules/engine.go

func (e *Engine) PersistRule(name string, config *config.Config) error {
    e.mu.Lock()
    defer e.mu.Unlock()

    // Find runtime rule
    var rule *CustomRule
    for i, r := range e.runtimeRules {
        if r.Name == name {
            rule = &e.runtimeRules[i]
            break
        }
    }
    if rule == nil {
        return fmt.Errorf("runtime rule %q not found", name)
    }

    // Add to config rules
    configRule := config.CustomRule{
        Name:        rule.Name,
        Description: rule.Description,
        Enabled:     rule.Enabled,
        Condition:   rule.Condition,
        Action:      rule.Action,
        Reason:      rule.Reason,
    }
    config.Rules.Custom = append(config.Rules.Custom, configRule)

    // Remove from runtime rules
    e.runtimeRules = append(e.runtimeRules[:i], e.runtimeRules[i+1:]...)

    return nil
}

func (e *Engine) PersistAllRules(config *config.Config) ([]string, error) {
    var persisted []string
    for _, rule := range e.runtimeRules {
        if err := e.PersistRule(rule.Name, config); err != nil {
            return persisted, err
        }
        persisted = append(persisted, rule.Name)
    }
    return persisted, nil
}
```

