```go
// pkg/daemon/handlers_rules.go

func (s *Server) handlePersistRule(w http.ResponseWriter, r *http.Request) {
    name := chi.URLParam(r, "name")

    // Get current config
    config, err := config.LoadConfig(s.workDir)
    if err != nil {
        http.Error(w, err.Error(), 500)
        return
    }

    // Persist rule
    if err := s.rulesEngine.PersistRule(name, config); err != nil {
        http.Error(w, err.Error(), 400)
        return
    }

    // Save config
    if err := config.Save(s.workDir); err != nil {
        http.Error(w, err.Error(), 500)
        return
    }

    json.NewEncoder(w).Encode(map[string]interface{}{
        "success": true,
        "rule":    s.rulesEngine.GetRule(name),
    })
}
